      "summary": "华为于10月13日在上海练秋湖研发中心召开时隔六年的麒麟芯片技术交流会，首次系统介绍逻辑折叠量产进展。2023年以来基于麒麟芯片的终端产品累计发货超1亿部，麒麟9050系列首次实现逻辑折叠量产，晶体管密度提升53.5%，麒麟9050 Pro的CPU大核能效提升41%、NPU算力提升140%，当前混合键合间距为1.5微米",
